#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minSwaps(vector<int>& nums, vector<int>& forbidden) {
        int n = nums.size();
        unordered_map<int, int> counts;
        int k = 0, max_freq = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == forbidden[i]) {
                k++;
                counts[nums[i]]++;
                max_freq = max(max_freq, counts[nums[i]]);
            }
        }
        if (k == 0) return 0;
        return max((k + 1) / 2, max_freq);
    }
};

import java.util.*;

class Solution {
    public int minSwaps(int[] nums, int[] forbidden) {
        int n = nums.length;
        Map<Integer, Integer> counts = new HashMap<>();
        int k = 0, maxFreq = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == forbidden[i]) {
                k++;
                int cnt = counts.getOrDefault(nums[i], 0) + 1;
                counts.put(nums[i], cnt);
                maxFreq = Math.max(maxFreq, cnt);
            }
        }
        if (k == 0) return 0;
        return Math.max((k + 1) / 2, maxFreq);
    }
}

var minSwaps = function(nums, forbidden) {
    const counts = new Map();
    let k = 0, maxFreq = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === forbidden[i]) {
            k++;
            const cnt = (counts.get(nums[i]) || 0) + 1;
            counts.set(nums[i], cnt);
            maxFreq = Math.max(maxFreq, cnt);
        }
    }
    if (k === 0) return 0;
    return Math.max(Math.floor((k + 1) / 2), maxFreq);
};
